-- Easy Beans' dogs (business 1), as the owners asked:
--  * Cooper is Aron's again, with his photo (the `people_page_and_pets` migration gave him to Mark).
--  * Fudge is back on Aron's account with his photo (that migration took him off along with the rest of
--    Aron's pets; his photo is the one the `pet_photos` migration gave him).
--  * Yoda's photo is cut closer, around his face (from the one the `pet_photos` migration gave him).
-- Aron and Mark are found as in the `people_page_and_pets` migration. A pet can't change hands (pet_rules
-- keeps its person), so Cooper is added to Aron with Mark's name, kind, breed and photo for him, and
-- Mark's goes. A pet Aron already has keeps what it has (Fudge gets the photo only if he has none), and
-- Yoda's photo changes only while it's none or still that first one, so a photo someone has put on since
-- stays. With no Aron, nothing changes; running it again changes nothing.
do $$
declare
  v_fudge constant text := 'data:image/jpeg;base64,';
  v_yoda constant text := 'data:image/jpeg;base64,';
  v_aron uuid;
  v_mark uuid;
  v_cooper uuid;
  v_kind text;
  v_breed text;
  v_photo text;
begin
  select p.id into v_aron from public.profiles p
   where p.business_id = 1 and p.role in ('admin', 'employee') and p.full_name ~* '^\s*aron\M'
   order by (p.role = 'admin' and p.can_see_pay) desc, p.active desc, p.created_at limit 1;
  select p.id into v_mark from public.profiles p
   where p.business_id = 1 and p.role in ('admin', 'employee') and p.full_name ~* '^\s*mark\M'
   order by (p.role = 'admin' and p.can_see_pay) desc, p.active desc, p.created_at limit 1;
  if v_aron is null then return; end if;

  -- Fudge first, as he was: on Aron's account with his photo.
  update public.pets set photo = v_fudge where profile_id = v_aron and name = 'Fudge' and photo is null;
  if not exists (select 1 from public.pets where profile_id = v_aron and name = 'Fudge') then
    insert into public.pets (business_id, profile_id, name, kind, sort, photo)
    select 1, v_aron, 'Fudge', 'dog', coalesce(max(sort), 0) + 1, v_fudge from public.pets where profile_id = v_aron;
  end if;

  -- Cooper: from Mark's account to Aron's, as Mark has him.
  if v_mark is not null and not exists (select 1 from public.pets where profile_id = v_aron and name = 'Cooper') then
    select x.id, x.kind, x.breed, x.photo into v_cooper, v_kind, v_breed, v_photo
      from public.pets x where x.profile_id = v_mark and x.name = 'Cooper' order by x.created_at limit 1;
    if v_cooper is not null then
      insert into public.pets (business_id, profile_id, name, kind, breed, sort, photo)
      select 1, v_aron, 'Cooper', v_kind, v_breed, coalesce(max(sort), 0) + 1, v_photo from public.pets where profile_id = v_aron;
      delete from public.pets where id = v_cooper;
    end if;
  end if;

  -- Yoda, closer.
  update public.pets set photo = v_yoda
   where business_id = 1 and name = 'Yoda' and profile_id in (v_aron, v_mark)
     and (photo is null or md5(photo) = '946beba06253d72e05160df4f7597b4a');
end $$;
